const resp = $json;
const boards = (resp.data && resp.data.boards) || [];
if (!boards.length) {
  return [{ json: { error: 'No boards returned. Check your MONDAY_CONTACTS_BOARD_ID / MONDAY_LEADS_BOARD_ID env vars and the attached Monday credential.', raw: resp } }];
}

const contactsBoardId = String($env.MONDAY_CONTACTS_BOARD_ID || '');
const leadsBoardId = String($env.MONDAY_LEADS_BOARD_ID || '');
const contacts = boards.find(b => String(b.id) === contactsBoardId);
const leads = boards.find(b => String(b.id) === leadsBoardId);

// Column title -> env var name mapping
const CONTACTS_COL_MAP = {
  'Lead Name': 'MONDAY_COL_CONTACT_NAME',
  'Email': 'MONDAY_COL_CONTACT_EMAIL',
  'Email Confidence': 'MONDAY_COL_CONTACT_EMAIL_CONFIDENCE',
  'Company': 'MONDAY_COL_CONTACT_COMPANY',
  'Source': 'MONDAY_COL_CONTACT_SOURCE',
  'Date Added': 'MONDAY_COL_CONTACT_DATE_ADDED',
  'Status': 'MONDAY_COL_CONTACT_STATUS'
};
const CONTACTS_GROUP_MAP = {
  'New Active Contacts': 'MONDAY_GROUP_NEW_ACTIVE_CONTACTS'
};
const LEADS_COL_MAP = {
  'Lead Name': 'MONDAY_COL_LEAD_NAME',
  'Email': 'MONDAY_COL_LEAD_EMAIL',
  'Company': 'MONDAY_COL_LEAD_COMPANY',
  'Status': 'MONDAY_COL_LEAD_STATUS',
  'Send Date': 'MONDAY_COL_LEAD_SEND_DATE',
  'Subject Line Used': 'MONDAY_COL_LEAD_SUBJECT_LINE',
  'Email Body Snippet': 'MONDAY_COL_LEAD_EMAIL_BODY_SNIPPET',
  'Reply Received Date': 'MONDAY_COL_LEAD_REPLY_RECEIVED_DATE',
  'Reply Snippet': 'MONDAY_COL_LEAD_REPLY_SNIPPET',
  'Follow Up 1 Sent': 'MONDAY_COL_LEAD_FOLLOW_UP_1_SENT',
  'Follow Up 2 Sent': 'MONDAY_COL_LEAD_FOLLOW_UP_2_SENT',
  'Follow Up 1 Date': 'MONDAY_COL_LEAD_FOLLOW_UP_1_DATE',
  'Thread ID': 'MONDAY_COL_LEAD_THREAD_ID',
  'Approval Slack TS': 'MONDAY_COL_LEAD_APPROVAL_SLACK_TS',
  'Pending Draft': 'MONDAY_COL_LEAD_PENDING_DRAFT'
};
const LEADS_GROUP_MAP = {
  'New Pipeline': 'MONDAY_GROUP_NEW_PIPELINE',
  'Qualified Pipe, Reply': 'MONDAY_GROUP_QUALIFIED',
  'No Response': 'MONDAY_GROUP_NO_RESPONSE'
};

function resolve(board, mapObj, kind) {
  const out = {};
  const missing = [];
  const src = kind === 'columns' ? (board && board.columns) || [] : (board && board.groups) || [];
  const titleKey = kind === 'columns' ? 'title' : 'title';
  for (const [title, envName] of Object.entries(mapObj)) {
    const hit = src.find(s => (s[titleKey] || '').trim() === title);
    if (hit) { out[envName] = hit.id; } else { missing.push(`${envName} (looking for ${kind.slice(0,-1)} titled "${title}")`); }
  }
  return { out, missing };
}

const missing = [];
const resolved = {};
resolved.MONDAY_CONTACTS_BOARD_ID = contactsBoardId;
resolved.MONDAY_LEADS_BOARD_ID = leadsBoardId;

if (!contacts) missing.push(`Contacts board not found (MONDAY_CONTACTS_BOARD_ID=${contactsBoardId})`);
if (!leads) missing.push(`Leads board not found (MONDAY_LEADS_BOARD_ID=${leadsBoardId})`);

if (contacts) {
  const c = resolve(contacts, CONTACTS_GROUP_MAP, 'groups'); Object.assign(resolved, c.out); missing.push(...c.missing);
  const cc = resolve(contacts, CONTACTS_COL_MAP, 'columns'); Object.assign(resolved, cc.out); missing.push(...cc.missing);
}
if (leads) {
  const l = resolve(leads, LEADS_GROUP_MAP, 'groups'); Object.assign(resolved, l.out); missing.push(...l.missing);
  const lc = resolve(leads, LEADS_COL_MAP, 'columns'); Object.assign(resolved, lc.out); missing.push(...lc.missing);
}

const order = [
  'MONDAY_CONTACTS_BOARD_ID',
  'MONDAY_LEADS_BOARD_ID',
  '',
  '# Contacts Board',
  'MONDAY_GROUP_NEW_ACTIVE_CONTACTS',
  'MONDAY_COL_CONTACT_NAME',
  'MONDAY_COL_CONTACT_EMAIL',
  'MONDAY_COL_CONTACT_EMAIL_CONFIDENCE',
  'MONDAY_COL_CONTACT_COMPANY',
  'MONDAY_COL_CONTACT_SOURCE',
  'MONDAY_COL_CONTACT_DATE_ADDED',
  'MONDAY_COL_CONTACT_STATUS',
  '',
  '# Leads Board',
  'MONDAY_GROUP_NEW_PIPELINE',
  'MONDAY_GROUP_QUALIFIED',
  'MONDAY_GROUP_NO_RESPONSE',
  'MONDAY_COL_LEAD_NAME',
  'MONDAY_COL_LEAD_EMAIL',
  'MONDAY_COL_LEAD_COMPANY',
  'MONDAY_COL_LEAD_STATUS',
  'MONDAY_COL_LEAD_SEND_DATE',
  'MONDAY_COL_LEAD_SUBJECT_LINE',
  'MONDAY_COL_LEAD_EMAIL_BODY_SNIPPET',
  'MONDAY_COL_LEAD_REPLY_RECEIVED_DATE',
  'MONDAY_COL_LEAD_REPLY_SNIPPET',
  'MONDAY_COL_LEAD_FOLLOW_UP_1_SENT',
  'MONDAY_COL_LEAD_FOLLOW_UP_2_SENT',
  'MONDAY_COL_LEAD_FOLLOW_UP_1_DATE',
  'MONDAY_COL_LEAD_THREAD_ID',
  'MONDAY_COL_LEAD_APPROVAL_SLACK_TS',
  'MONDAY_COL_LEAD_PENDING_DRAFT'
];

const lines = order.map(k => {
  if (k === '') return '';
  if (k.startsWith('#')) return k;
  const v = resolved[k];
  return v != null ? `${k}=${v}` : `# ${k}=<MISSING — create this column/group in Monday>`;
});

const dotenvSnippet = lines.join('\n');
const yamlSnippet = lines.filter(l => l && !l.startsWith('#')).map(l => `      - ${l}`).join('\n');

return [{
  json: {
    status: missing.length === 0 ? 'ok' : 'incomplete',
    missing,
    resolved,
    dotenv_snippet: dotenvSnippet,
    docker_compose_snippet: `services:\n  n8n:\n    environment:\n${yamlSnippet}`
  }
}];
